import logging
import requests
from xml.etree import ElementTree
from taf.hw.rf_switch.devices.rf_switch import RfSwitch
from taf.hw.rf_switch.exceptions import RfSwitchActionNotSupported, RfSwitchActionFailed, RfSwitchConnectionFailed


logger = logging.getLogger(__name__)


class JFW(RfSwitch):
    """
    Module to control JFW based RF switches.
    """
    SUPPORTED_PORT_IN_VALUES = [str(value) for value in range(1, 9)]
    SUPPORTED_PORT_OUT_VALUES = ["1"]

    def __init__(self, ip):
        super().__init__()
        self.ip = ip

    def connect_ports(self, port_in, port_out="1"):
        """Disconnects previous connection and connects provided port_in with port_out.
        1. Check if port is not already connected
        2. Get currently connected port
        3. Turn off currently connected port
        4. Connect requested port
        5. Verify the connection was successful
        """
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        if self.get_port_in_status(port_in) != port_out:
            if port_out is not None:
                self._disconnect_currently_connected_port_in()
            self._toggle_port(port_in)
            self._verify_connection(port_in, expected_connection_status=True)

    def disconnect_ports(self, port_in, port_out="1"):
        """Disconnects provided port_in.
        1. Check if port is not already disconnected
        2. Disconnect requested port
        3. Verify the disconnection was successful
        """
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        if self.get_port_in_status(port_in) == port_out:
            self._toggle_port(port_in)
            self._verify_connection(port_in, expected_connection_status=False)

    def get_port_in_status(self, port_in):
        """
        Get rf switch status by url using ip address and port
        """
        if port_in not in self.SUPPORTED_PORT_IN_VALUES:
            error_msg = f'Given port_in: {port_in} is not supported.'
            raise RfSwitchActionFailed(error_msg)
        connection_dict = self.get_connected_ports()
        if port_in in connection_dict.keys():
            return connection_dict[port_in]

    def get_port_out_status(self, port_out="1"):
        if port_out not in self.SUPPORTED_PORT_OUT_VALUES:
            raise RfSwitchActionFailed(f'Given port_out: {port_out} is not supported.')
        connection_dict = self.get_connected_ports()
        connected_ports = list(connection_dict.keys())
        if not connected_ports:
            return None
        if len(connected_ports) > 1:
            raise RfSwitchActionNotSupported(f"There are multiple ports connected to port_out: {str(connected_ports)}.\n"
                                             "This is not recommended and therefore - not supported."
                                             )
        return connected_ports[0]

    def get_connected_ports(self):
        url = f'http://{self.ip}/status.xml'
        response = requests.get(url)
        xml_response = ElementTree.fromstring(response.content)
        connected_ports = {}
        for element in xml_response:
            if "led" in element.tag:
                port_in = element.tag.replace("led", "")
                port_out = element.text
                if port_in != "0" and port_out != "0":
                    connected_ports[port_in] = port_out
        return connected_ports

    def _toggle_port(self, port_in):
        """
        Toggle rf switch status for port
        Does nothing if None provided.
        """
        url = f"http://{self.ip}/leds.cgi?led={port_in}"
        response = requests.get(url)
        if response.status_code == 404:
            raise RfSwitchConnectionFailed(f"Could not connect with url: {url}")
        elif response.status_code != 200:
            raise RfSwitchActionFailed("Could not execute action on RfSwitch.\n"
                                       f"URL requested: {url}\n"
                                       f"Status code: {response.status_code}")

    def _verify_connection(self, port_in, expected_connection_status=True):
        connection_is_active = self.get_port_in_status(port_in) == "1"
        if connection_is_active != expected_connection_status:
            raise RfSwitchActionFailed(f"Rf Switch port {port_in} toggling failed")

    def _disconnect_currently_connected_port_in(self):
        currently_connected_port_in = self.get_port_out_status()
        if currently_connected_port_in is not None:
            self._toggle_port(currently_connected_port_in)


class JFW50S1650XX(JFW):
    """Works exactly like default JFW"""
